const themeButton=document.getElementById("themeToggle");
function setTheme(theme){document.documentElement.setAttribute("data-theme",theme);localStorage.setItem("inkverse-theme",theme);if(themeButton)themeButton.textContent=theme==="light"?"☀ Light":"☾ Theme";}
if(localStorage.getItem("inkverse-theme"))setTheme(localStorage.getItem("inkverse-theme"));
themeButton?.addEventListener("click",()=>setTheme(document.documentElement.getAttribute("data-theme")==="light"?"dark":"light"));
const searchInput=document.getElementById("searchInput"), genreFilter=document.getElementById("genreFilter"), cards=[...document.querySelectorAll(".book-card")];
function filterBooks(){if(!cards.length)return;const q=(searchInput?.value||"").trim().toLowerCase(),g=(genreFilter?.value||"all").toLowerCase();let n=0;cards.forEach(c=>{const show=c.dataset.title.includes(q)&&(g==="all"||c.dataset.genre.toLowerCase().includes(g));c.hidden=!show;if(show)n++;});const count=document.getElementById("resultCount");if(count)count.textContent=n;const empty=document.getElementById("noResults");if(empty)empty.hidden=n!==0;}
searchInput?.addEventListener("input",filterBooks);genreFilter?.addEventListener("change",filterBooks);
const details={"1": {"title": "Hunter x Hunter", "genre": "Adventure", "synopsis": "A young explorer enters a dangerous examination to find a missing mentor. New friends and sharp instincts help him face unexpected trials."}, "2": {"title": "Jujutsu Kaisen", "genre": "Supernatural", "synopsis": "When strange shadows gather beneath an abandoned station, a brave student discovers that courage means trusting a team."}, "3": {"title": "Wind Breaker", "genre": "Action", "synopsis": "A lone fighter arrives in a town where strength is measured by how well you protect others. One promise changes his view of friendship."}, "4": {"title": "Black Clover", "genre": "Fantasy", "synopsis": "In a kingdom ruled by magic, an apprentice with an unusual power refuses to give up. A forgotten spell may save a village."}, "5": {"title": "Chainsaw Man", "genre": "Dark Fantasy", "synopsis": "A young hunter accepts one last job in a city full of dangerous creatures. A fresh start always comes with a price."}, "6": {"title": "Bleach", "genre": "Supernatural", "synopsis": "A quiet teenager follows a glowing lantern into a hidden world where lost souls need help finding their way."}, "7": {"title": "Fullmetal Alchemist", "genre": "Fantasy", "synopsis": "Two siblings search for a legendary orchard said to restore what was lost. Their journey teaches them responsibility."}, "8": {"title": "Yu Yu Hakusho", "genre": "Supernatural", "synopsis": "A strange message appears on a school desk after sunset. A quick-witted teen follows clues across two worlds."}, "9": {"title": "Dandadan", "genre": "Sci-Fi", "synopsis": "A broken arcade machine begins predicting impossible events. Two classmates investigate a truth stranger than either expected."}, "10": {"title": "World Trigger", "genre": "Sci-Fi", "synopsis": "A portal flickers open above a peaceful city. A rookie defender learns that teamwork matters more than acting alone."}, "11": {"title": "Naruto", "genre": "Adventure", "synopsis": "A young ninja finds an old headband near a bridge and sets out to return it, learning the strength of loyalty."}, "12": {"title": "Hell's Paradise: Jigokuraku", "genre": "Dark Fantasy", "synopsis": "A scouting team reaches an island where flowers bloom without sunlight. The mission tests their trust and resolve."}, "13": {"title": "Soul Eater", "genre": "Fantasy", "synopsis": "At a school for unusual partners, a midnight bell rings from a locked tower. Two students discover the power of teamwork."}, "14": {"title": "Kagurabachi", "genre": "Action", "synopsis": "A young swordsmith inherits a mysterious blade and a promise he cannot ignore. He must decide what justice means."}, "15": {"title": "Gachiakuta", "genre": "Dystopian", "synopsis": "A resourceful teen falls into a forgotten district built from discarded things and uncovers the value hidden in them."}, "16": {"title": "Kaiju No. 8", "genre": "Sci-Fi", "synopsis": "A cleanup worker hears a warning siren before anyone else. Practical knowledge becomes vital when a giant creature appears."}, "17": {"title": "Demon Slayer", "genre": "Fantasy", "synopsis": "A young traveler follows wisteria lanterns to find a missing friend. Compassion helps them see beyond fear."}, "18": {"title": "The Seven Deadly Sins", "genre": "Fantasy", "synopsis": "A wandering knight searches for seven scattered symbols before a kingdom loses hope. Each symbol reveals a different kind of courage."}, "19": {"title": "Fire Force", "genre": "Supernatural", "synopsis": "A rookie firefighter joins a special team investigating mysterious flames. Quick thinking matters as much as bravery."}, "20": {"title": "Blue Exorcist", "genre": "Supernatural", "synopsis": "A student discovers strange chalk circles around an academy. Understanding the mystery becomes better than fearing it."}, "21": {"title": "Undead Unluck", "genre": "Fantasy", "synopsis": "A girl whose luck ruins every plan meets an adventurer who refuses to give up. Together they turn a trip into a rescue."}, "22": {"title": "Tokyo Ghoul", "genre": "Horror", "synopsis": "A student gets lost in a night market where every stall hides a secret. To get home, he must decide whom to trust."}, "23": {"title": "JoJo's Bizarre Adventure", "genre": "Adventure", "synopsis": "A curious heir enters a mansion where every clock runs backward. Solving the puzzle reveals a family secret."}, "24": {"title": "Attack on Titan", "genre": "Dystopian", "synopsis": "A patrol notices a missing stone in a massive city wall. Their investigation uncovers an old warning."}, "25": {"title": "Sakamoto Days", "genre": "Action / Comedy", "synopsis": "A quiet shop owner plans an ordinary day until a runaway delivery cart sparks a citywide chase."}, "26": {"title": "The Promised Neverland", "genre": "Mystery", "synopsis": "A group of clever children discovers a coded page hidden in a library. Their teamwork may reveal a way out."}, "27": {"title": "Black Torch", "genre": "Supernatural", "synopsis": "A teen who understands animals befriends a mysterious black cat. An eerie shadow tests their unusual bond."}, "28": {"title": "Parasyte", "genre": "Sci-Fi / Horror", "synopsis": "A strange organism appears in a greenhouse after a meteor shower. A science club investigates to protect the neighborhood."}, "29": {"title": "Ragnarok", "genre": "Mythic Fantasy", "synopsis": "A young challenger enters an ancient arena where legends are tested. Victory depends on knowing when to trust an ally."}, "30": {"title": "Mashle: Magic and Muscles", "genre": "Fantasy / Comedy", "synopsis": "In a school where magic decides status, a determined student enters a ridiculous tournament with an unusual talent."}};
const modal=document.getElementById("detailsModal");
function openDetails(id){const d=details[id];if(!d||!modal)return;document.getElementById("modalTitle").textContent=d.title;document.getElementById("modalGenre").textContent=d.genre;document.getElementById("modalSynopsis").textContent=d.synopsis;document.getElementById("modalRead").href=`stories/story-${id}.html`;modal.classList.add("show");}
document.querySelectorAll("[data-details]").forEach(b=>b.addEventListener("click",()=>openDetails(b.dataset.details)));
document.getElementById("modalClose")?.addEventListener("click",()=>modal?.classList.remove("show"));modal?.addEventListener("click",e=>{if(e.target===modal)modal.classList.remove("show");});document.addEventListener("keydown",e=>{if(e.key==="Escape")modal?.classList.remove("show");});
document.querySelectorAll("[data-like]").forEach(b=>{const key="inkverse-"+b.dataset.like;let liked=localStorage.getItem(key)==="true";function draw(){b.classList.toggle("liked",liked);b.textContent=liked?"♥ Liked":"♡ Like";}draw();b.addEventListener("click",()=>{liked=!liked;localStorage.setItem(key,String(liked));draw();});});
const progress=document.getElementById("readingProgress");function onScroll(){if(progress){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?Math.min(100,scrollY/max*100):0)+"%";}const b=document.getElementById("backTop");if(b)b.style.display=scrollY>500?"block":"none";}
window.addEventListener("scroll",onScroll);document.getElementById("backTop")?.addEventListener("click",()=>scrollTo({top:0,behavior:"smooth"}));

