if(reader&&readerId&&chapterText[readerId]){
  const article=reader.querySelector(".story-content");
  const ending=article?.querySelector(".ending");
  if(article&&ending){
    article.querySelectorAll("p:not(.ending)").forEach(paragraph=>paragraph.remove());
    [
      ...chapterText[readerId].slice(0,2),
      chapterScenes[readerId],
      ...chapterText[readerId].slice(2),
      chapterAfterwords[readerId]
    ].forEach(text=>{
      const paragraph=document.createElement("p");
      paragraph.textContent=text;
      article.insertBefore(paragraph,ending);
    });
  }
}
